custom_qss:
/* ============================================================
   REDLINE part 1 — base, window, menubar, menus
   Aesthetic: black everything, every outline red, ZERO translucency
   ============================================================ */

* {
    border: 1px solid #3a1010;
    background-color: #120606 !important;
    color: #cc6666 !important;
}

/* ---------- window: opaque near-black with a faint red cast ---------- */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.04, y2:1,
        stop:0 #140707, stop:0.5 #0a0303, stop:1 #050202) !important;
    border: 1px solid #3a10102;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0.04, y2:1,
        stop:0 #140707, stop:0.5 #0a0303, stop:1 #050202) !important;
    border: 1px solid #3a10102;
}

/* ---------- menubar ---------- */
QMenuBar {
    background-color: #0a0303 !important;
    border: 1px solid #3a1010;
    border-top: none;
}
QMenuBar::item {
    padding: 5px 12px;
    border-radius: 3px;
    background-color: #0a0303 !important;
    color: #cc6666_DIM !important;
}
QMenuBar::item:selected {
    background-color: #240b0c !important;
    border: 1px solid #ff5566;
    color: #cc6666 !important;
}
QMenuBar::item:disabled {
    color: #4a2525 !important;
}

/* ---------- popup card ---------- */
QMenu {
    background-color: #0a0303 !important;
    border: 1px solid #ff5566;
    border-radius: 6px;
    padding: 6px;
}
QMenu::item {
    padding: 6px 24px 6px 14px;
    border-radius: 4px;
    background-color: transparent !important;
    color: #cc6666 !important;
}
QMenu::item:selected {
    background-color: #cc2233FILL !important;
    border: 1px solid #cc2233;
    color: #ffb3b3 !important;
}
QMenu::item:disabled {
    color: #4a2525 !important;
}
QMenu::separator {
    height: 1px;
    background-color: #3a1010;
    margin: 6px 8px;
}
QMenu::icon {
    padding-left: 6px;
}

/* ============================================================
   REDLINE part 2 — toolbars, buttons, inputs, checkboxes
   ============================================================ */

/* ---------- toolbar chrome ---------- */
QToolBar {
    background-color: #0a0303 !important;
    border: 1px solid #3a1010;
    spacing: 3px;
    padding: 4px;
}
QToolBar::separator {
    background-color: #3a1010;
    width: 1px;
    margin: 6px 4px;
}
QToolBar QToolButton {
    background-color: transparent !important;
    padding: 5px 8px;
    border-radius: 5px;
    color: #cc6666_DIM !important;
}
QToolBar QToolButton:hover {
    background-color: #cc2233FILL !important;
    border: 1px solid #cc2233;
    color: #ffb3b3 !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background-color: #240b0c !important;
    border: 1px solid #ff5566;
    border-bottom: 2px solid #cc2233;
    color: #ffb3b3 !important;
}
QToolBar QToolButton:disabled {
    color: #4a2525 !important;
}

QToolButton {
    background-color: transparent !important;
    padding: 5px 8px;
    border-radius: 5px;
    color: #cc6666_DIM !important;
}
QToolButton:hover {
    background-color: #cc2233FILL !important;
    border: 1px solid #cc2233;
    color: #ffb3b3 !important;
}
QToolButton:checked, QToolButton:pressed {
    background-color: #240b0c !important;
    border: 1px solid #ff5566;
    border-bottom: 2px solid #cc2233;
    color: #ffb3b3 !important;
}
QToolButton:disabled {
    color: #4a2525 !important;
}

/* ---------- buttons: opaque black, red outline, hot hover ---------- */
QPushButton {
    background-color: #120606 !important;
    border: 1px solid #3a10102;
    border-radius: 5px;
    padding: 6px 18px;
    color: #cc6666 !important;
}
QPushButton:hover {
    background-color: #1a0808 !important;
    border: 1px solid #cc2233;
    color: #ffb3b3 !important;
}
QPushButton:pressed {
    background-color: #cc2233FILL !important;
    border: 1px solid #cc2233;
    color: #ffb3b3 !important;
    padding: 7px 17px 5px 19px;
}
QPushButton:checked {
    background-color: #240b0c !important;
    border: 1px solid #ff5566;
    border-bottom: 2px solid #cc2233;
    color: #ffb3b3 !important;
}
QPushButton:default {
    border: 1px solid #ff5566;
}
QPushButton:disabled {
    background-color: #0a0303 !important;
    border: 1px solid #3a1010;
    color: #4a2525 !important;
}
QPushButton::menu-indicator {
    subcontrol-origin: margin;
    width: 14px;
    height: 10px;
    border: none;
}

/* ---------- inputs: black fields, red focus ring ---------- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background-color: #050202 !important;
    border: 1px solid #3a1010;
    border-radius: 4px;
    padding: 5px 8px;
    color: #ffb3b3 !important;
    selection-background-color: #cc2233FILL;
    selection-color: #ffb3b3;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border: 1px solid #ff5566;
    background-color: #0a0303 !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #4a2525 !important;
    border: 1px solid #3a1010;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background-color: #120606 !important;
    border: none;
    width: 16px;
}

QComboBox {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
    border-radius: 4px;
    padding: 5px 8px;
    color: #ffb3b3 !important;
}
QComboBox:hover {
    border: 1px solid #cc2233;
}
QComboBox:focus {
    border: 1px solid #ff5566;
}
QComboBox::drop-down {
    border: none;
    background-color: #120606 !important;
    width: 18px;
}
QComboBox QAbstractItemView {
    background-color: #0a0303 !important;
    border: 1px solid #ff5566;
    border-radius: 5px;
    padding: 4px;
    selection-background-color: #cc2233FILL;
    selection-color: #ffb3b3;
}
QComboBox:disabled {
    color: #4a2525 !important;
    border: 1px solid #3a1010;
}

/* ---------- checkboxes: red outline boxes, solid red check ---------- */
QCheckBox, QRadioButton {
    color: #cc6666 !important;
    background-color: transparent !important;
    padding: 3px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 15px;
    height: 15px;
    background-color: #050202 !important;
    border: 1px solid #3a10102;
    border-radius: 4px;
}
QRadioButton::indicator {
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    border: 1px solid #ff5566;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background-color: #240b0c !important;
    border: 1px solid #cc2233;
}
QCheckBox:disabled, QRadioButton:disabled {
    color: #4a2525 !important;
}
QRadioButton::indicator:disabled, QCheckBox::indicator:disabled {
    background-color: #0a0303 !important;
    border: 1px solid #3a1010;
}

/* ============================================================
   REDLINE part 3 — tabs, docks, groupboxes, item views, headers
   ============================================================ */

/* ---------- tabs: red underline on selected ---------- */
QTabBar {
    background-color: #0a0303 !important;
    border: none;
}
QTabBar::tab {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
    border-radius: 4px 4px 0 0;
    padding: 7px 18px;
    margin: 0 1px;
    color: #cc6666_DIM !important;
}
QTabBar::tab:hover {
    background-color: #1a0808 !important;
    border: 1px solid #cc2233;
    color: #ffb3b3 !important;
}
QTabBar::tab:selected {
    background-color: #240b0c !important;
    border: 1px solid #ff5566;
    border-bottom: 2px solid #cc2233;
    color: #ffb3b3 !important;
}
QTabBar::tab:disabled {
    color: #4a2525 !important;
}
QTabBar::close-button {
    background-color: transparent !important;
    border: none;
    border-radius: 3px;
}
QTabBar::close-button:hover {
    background-color: #cc2233FILL !important;
    border: 1px solid #cc2233;
}
QTabWidget {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
}
QTabWidget::pane {
    border: 1px solid #3a1010;
    background-color: #120606 !important;
}

/* ---------- docks: black body, bright tick + hot title strip ---------- */
QDockWidget {
    background-color: #0a0303 !important;
    border: 1px solid #3a1010;
}
QDockWidget::title {
    background-color: #140707 !important;
    border: 1px solid #3a10102;
    border-bottom: 2px solid #cc2233;
    padding: 7px 10px;
    color: #ffb3b3 !important;
    font-weight: 600;
}
QDockWidget::close-button, QDockWidget::float-button {
    background-color: transparent !important;
    border: none;
    padding: 2px;
    border-radius: 3px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background-color: #cc2233FILL !important;
    border: 1px solid #cc2233;
}

/* ---------- group boxes: red title, boxed like the original ---------- */
QGroupBox {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
    border-radius: 5px;
    margin-top: 14px;
    padding-top: 8px;
    font-weight: 600;
    color: #cc6666 !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 7px;
    background-color: #0a0303 !important;
    border: 1px solid #3a10102;
    border-radius: 3px;
    color: #ffb3b3 !important;
}

/* ---------- item views: black lists, red selection ---------- */
QAbstractItemView {
    background-color: #050202 !important;
    border: 1px solid #3a1010;
    border-radius: 5px;
    alternate-background-color: #0d0404;
    selection-background-color: #240b0c;
    selection-color: #ffb3b3;
    outline: none;
}
QAbstractItemView::item {
    padding: 4px;
    border: none;
}
QAbstractItemView::item:hover {
    background-color: #1a0808 !important;
}
QAbstractItemView::item:selected {
    background-color: #240b0c !important;
    border-left: 3px solid #cc2233;
    color: #ffb3b3 !important;
}
QAbstractItemView::item:selected:!active {
    background-color: #170909 !important;
    border-left: 3px solid #3a10102;
}
QTreeView::item, QTreeWidget::item, QTreeWidgetItem,
QTableView::item, QListView::item, QListWidget::item {
    background-color: transparent !important;
}
QTableView {
    gridline-color: #3a1010;
}

QHeaderView {
    background-color: #0a0303 !important;
    border: none;
}
QHeaderView::section {
    background-color: #140707 !important;
    border: none;
    border-right: 1px solid #3a1010;
    border-bottom: 1px solid #3a10102;
    padding: 6px 8px;
    color: #cc6666_DIM !important;
    font-weight: 600;
}
QHeaderView::section:hover {
    background-color: #1a0808 !important;
    color: #ffb3b3 !important;
}

/* ============================================================
   REDLINE part 4 — scrollbars, sliders, progress, status, misc
   ============================================================ */

/* ---------- scrollbars: black track, red-lined handle ---------- */
QScrollBar:vertical {
    background-color: #0a0303 !important;
    border: 1px solid #3a1010;
    width: 13px;
    margin: 0;
}
QScrollBar::handle:vertical {
    background-color: #1a0808 !important;
    border: 1px solid #3a10102;
    border-radius: 4px;
    min-height: 30px;
}
QScrollBar::handle:vertical:hover {
    background-color: #240b0c !important;
    border: 1px solid #cc2233;
}
QScrollBar::handle:vertical:pressed {
    background-color: #cc2233FILL !important;
    border: 1px solid #ff5566;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 14px;
    background-color: #120606 !important;
    border: 1px solid #3a1010;
}
QScrollBar::add-line:vertical:hover, QScrollBar::sub-line:vertical:hover {
    background-color: #1a0808 !important;
    border: 1px solid #cc2233;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background-color: #0a0303 !important;
}
QScrollBar:horizontal {
    background-color: #0a0303 !important;
    border: 1px solid #3a1010;
    height: 13px;
    margin: 0;
}
QScrollBar::handle:horizontal {
    background-color: #1a0808 !important;
    border: 1px solid #3a10102;
    border-radius: 4px;
    min-width: 30px;
}
QScrollBar::handle:horizontal:hover {
    background-color: #240b0c !important;
    border: 1px solid #cc2233;
}
QScrollBar::handle:horizontal:pressed {
    background-color: #cc2233FILL !important;
    border: 1px solid #ff5566;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 14px;
    background-color: #120606 !important;
    border: 1px solid #3a1010;
}
QScrollBar::add-line:horizontal:hover, QScrollBar::sub-line:horizontal:hover {
    background-color: #1a0808 !important;
    border: 1px solid #cc2233;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background-color: #0a0303 !important;
}
QScrollBar::corner {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
}

/* ---------- sliders: black groove, solid red fill ---------- */
QSlider::groove:horizontal {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
    height: 5px;
    border-radius: 2px;
}
QSlider::sub-page:horizontal {
    background-color: #240b0c !important;
    border: 1px solid #cc2233;
    border-radius: 2px;
}
QSlider::add-page:horizontal {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background-color: #1a0808 !important;
    border: 1px solid #ff5566;
    width: 13px;
    margin: -5px 0;
    border-radius: 6px;
}
QSlider::handle:horizontal:hover {
    background-color: #cc2233FILL !important;
    border: 1px solid #ff5566;
}
QSlider::groove:vertical {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
    width: 5px;
    border-radius: 2px;
}
QSlider::sub-page:vertical {
    background-color: #240b0c !important;
    border: 1px solid #cc2233;
    border-radius: 2px;
}
QSlider::add-page:vertical {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
    border-radius: 2px;
}
QSlider::handle:vertical {
    background-color: #1a0808 !important;
    border: 1px solid #ff5566;
    height: 13px;
    margin: 0 -5px;
    border-radius: 6px;
}
QSlider::handle:vertical:hover {
    background-color: #cc2233FILL !important;
    border: 1px solid #ff5566;
}

/* ---------- progress: red gradient chunk on black ---------- */
QProgressBar {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
    border-radius: 5px;
    text-align: center;
    color: #ffb3b3 !important;
    min-height: 15px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #4d0000, stop:1 #cc2233) !important;
    border: 1px solid #cc2233;
    border-radius: 4px;
}

/* ---------- statusbar ---------- */
QStatusBar {
    background-color: #0a0303 !important;
    border: 1px solid #3a1010;
    border-left: none;
    border-bottom: none;
    border-right: none;
    color: #cc6666_DIM !important;
}
QStatusBar::item {
    background-color: transparent !important;
}
QStatusBar QLabel {
    color: #cc6666_DIM !important;
}

/* ---------- tooltip ---------- */
QToolTip {
    background-color: #140707 !important;
    border: 1px solid #ff5566;
    border-radius: 5px;
    padding: 6px 9px;
    color: #ffb3b3 !important;
}

/* ---------- splitters ---------- */
QSplitter {
    background-color: #0a0303 !important;
    border: none;
}
QSplitter::handle {
    background-color: #0a0303 !important;
    border: 1px solid #3a1010;
}
QSplitter::handle:hover {
    background-color: #1a0808 !important;
    border: 1px solid #cc2233;
}

/* ---------- frames / plain widgets stay opaque black ---------- */
QFrame, QStackedWidget, QScrollArea, QAbstractScrollArea, QWidget {
    background-color: #120606 !important;
    border: 1px solid #3a1010;
}
